import{U as e,W as t,j as n,nt as r}from"./chunks/framework.HOVv_sfg.js";var i=JSON.parse(`{"title":"Catalogues","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"pages/catalogue.md","filePath":"pages/catalogue.md"}`),a={name:`pages/catalogue.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="catalogues" tabindex="-1">Catalogues <a class="header-anchor" href="#catalogues" aria-label="Permalink to “Catalogues”">​</a></h1><p>A collection of major catalogues used to identify and classify musical works.</p><h2 id="listings" tabindex="-1">Listings <a class="header-anchor" href="#listings" aria-label="Permalink to “Listings”">​</a></h2><h3 id="rv-·-ryom-verzeichnis" tabindex="-1">RV · Ryom-Verzeichnis <a class="header-anchor" href="#rv-·-ryom-verzeichnis" aria-label="Permalink to “RV · Ryom-Verzeichnis”">​</a></h3><p><strong>Antonio Vivaldi</strong></p><p>The <em>Ryom-Verzeichnis</em> (RV) is the standard catalogue of works by Antonio Vivaldi, compiled by the Danish musicologist Peter Ryom.</p><p><a href="/pages/catalogues/rv.html">Browse RV catalogue</a></p><h3 id="twv-·-telemann-werke-verzeichnis" tabindex="-1">TWV · Telemann-Werke-Verzeichnis <a class="header-anchor" href="#twv-·-telemann-werke-verzeichnis" aria-label="Permalink to “TWV · Telemann-Werke-Verzeichnis”">​</a></h3><p><strong>Georg Philipp Telemann</strong></p><p>The <em>Telemann-Werke-Verzeichnis</em> (TWV) is the catalogue system used to identify the works of Georg Philipp Telemann.</p><p><a href="/pages/catalogues/twv.html">Browse TWV catalogue</a></p><h2 id="catalogue-information" tabindex="-1">Catalogue Information <a class="header-anchor" href="#catalogue-information" aria-label="Permalink to “Catalogue Information”">​</a></h2><table tabindex="0"><thead><tr><th>Catalogue</th><th>Composer</th><th>Compiler / Reference</th><th>Type</th></tr></thead><tbody><tr><td>RV</td><td>Antonio Vivaldi</td><td>Peter Ryom</td><td>Work catalogue</td></tr><tr><td>TWV</td><td>Georg Philipp Telemann</td><td>Martin Ruhnke et al.</td><td>Work catalogue</td></tr><tr><td>BWV</td><td>Johann Sebastian Bach</td><td>Wolfgang Schmieder</td><td>Work catalogue</td></tr><tr><td>HWV</td><td>George Frideric Handel</td><td>Bernd Baselt</td><td>Work catalogue</td></tr><tr><td>K.</td><td>Wolfgang Amadeus Mozart</td><td>Ludwig von Köchel</td><td>Work catalogue</td></tr></tbody></table><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to “About”">​</a></h2><p>Catalogue numbers provide a standardized way to identify individual musical works. Different composers use different catalogue systems, and a single work may sometimes be identified by more than one catalogue number.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};